def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    officer_patches = image_patch.find("officer")
    wilkins_patches = [o for o in officer_patches if o.best_text_match(["Wilkins"])]

    if not wilkins_patches:
        return image_patch

    wilkins = wilkins_patches[0]
    cake_patches = image_patch.find("cake")

    if not cake_patches:
        return wilkins

    cake = cake_patches[0]

    other_officers = [o for o in officer_patches if o != wilkins]

    if not other_officers:
        return cake

    other_officer_patches = [image_patch.crop(o.left, o.lower, o.right, o.upper) for o in other_officers]

    return ImagePatch(image, *min(other_officer_patches, key=lambda p: distance(wilkins, p)))

