def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    military_men = image_patch.find("military man")
    if not military_men: return image_patch

    # Sort by vertical center to find the middle man
    military_men.sort(key=lambda p: p.vertical_center)
    middle_man = military_men[len(military_men) // 2]

    # Find the two military men on either side of the middle man
    left_man = None
    right_man = None
    for man in military_men:
        if man.horizontal_center < middle_man.horizontal_center and not right_man:
            left_man = man
        elif man.horizontal_center > middle_man.horizontal_center and not left_man:
            right_man = man

    # Check if both sides are found
    if left_man and right_man:
        return middle_man
    else:
        return image_patch

