modern_c2_q7.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    light_patches = image_patch.find("light")
    bulb_patches = image_patch.find("bulb")

    if not light_patches or not bulb_patches:
        return image_patch

    light_patches = [l for l in light_patches if l.verify_property("light", "yellow")]
    light_patches = sorted(light_patches, key=lambda l: -l.vertical_center)

    visible_lights = []
    for light in light_patches:
        visible = True
        for bulb in bulb_patches:
            if light.overlaps_with(bulb.left, bulb.lower, bulb.right, bulb.upper):
                visible = False
                break
        if visible:
            visible_lights.append(light)

    return visible_lights[0] if visible_lights else light_patches[0]

