def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    computers = image_patch.find("computer")
    hands = image_patch.find("hand")

    if not computers or not hands:
        return image_patch

    right_hand_computers = []
    for comp in computers:
        for hand in hands:
            if comp.overlaps_with(hand.left, hand.lower, hand.right, hand.upper):
                right_hand_computers.append(comp)

    if not right_hand_computers:
        return image_patch

    rightmost_computer = max(right_hand_computers, key=lambda c: c.right)
    return rightmost_computer

